import farming_gif from '@/assets/images/farms.gif'
import farming_png from '@/assets/images/icon_farms@2x.png'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { cancelBubble } from '@cetus/utils'
import { HStack, Image, Text, Tooltip } from '@chakra-ui/react'
import { useState } from 'react'
import { useNavigate } from 'react-router-dom'

const FarmingIcon = () => {
  const navigate = useNavigate()
  const [isShowGif, setIsShowGif] = useState(false)
  const { isApp } = useWindowWidth()
  return (
    <HStack
      w="20px"
      h="20px"
      onClick={e => {
        cancelBubble(e)
        isApp ? '' : navigate('/farms')
      }}
      onMouseEnter={() => setIsShowGif(true)}
      onMouseLeave={() => {
        setIsShowGif(false)
      }}
    >
      <Tooltip label={<Text fontSize="12px">Farm rewards available</Text>} aria-label="Yield" placement="top">
        <button>
          {isShowGif ? (
            <Image
              w="100%"
              h="100%"
              src={farming_gif}
              onMouseLeave={() => {
                setIsShowGif(false)
              }}
            />
          ) : (
            <Image w="100%" h="100%" src={farming_png} onMouseEnter={() => setIsShowGif(true)} />
          )}
        </button>
      </Tooltip>
    </HStack>
  )
}

export default FarmingIcon
