import pool_img from '@/assets/images/icon_pools@2x.png'
import { AddressCopyLink, Block } from '@cetus/design'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { CoinPairImage, SingleCoinImage } from '@cetus/ui-kit'
import { cancelBubble } from '@cetus/utils'
import { Box, Center, HStack, Image, Popover, PopoverBody, PopoverContent, PopoverTrigger, Portal, Text, VStack } from '@chakra-ui/react'
import { useState } from 'react'

const CoinPairInfo = ({ poolInfo }: { poolInfo: any }) => {
  const [isShowInfo, setIsShowInfo] = useState(false)

  return (
    <HStack p="12px 0" onClick={e => cancelBubble(e)} onMouseEnter={() => setIsShowInfo(true)} onMouseLeave={() => setIsShowInfo(false)}>
      <Popover isOpen={isShowInfo} placement="top-start">
        <PopoverTrigger>
          <Center>
            <PoolShowInfo poolInfo={poolInfo} />
          </Center>
        </PopoverTrigger>
        {isShowInfo && (
          <Portal>
            <PopoverContent zIndex="2" minW="unset" w="unset" border="1px solid" borderColor="border" p="4px ">
              <PopoverBody borderRadius="12px">
                <TooltipInfo poolInfo={poolInfo} />
              </PopoverBody>
            </PopoverContent>
          </Portal>
        )}
      </Popover>
    </HStack>
  )
}

const PoolShowInfo = ({ poolInfo }: { poolInfo: any }) => {
  return (
    <HStack>
      <CoinPairImage
        showATag={!poolInfo?.displayTokenA?.is_trusted}
        showBTag={!poolInfo?.displayTokenB?.is_trusted}
        coinAIconUrl={poolInfo?.displayTokenA?.logo_url}
        coinBIconUrl={poolInfo?.displayTokenB?.logo_url}
      />
      <VStack>
        <HStack>
          <Text color="text_caption">{poolInfo?.name}</Text>
          <Block w="unset" p="2px 8px" borderRadius="12px">
            <Text fontSize="12px" color="primary">
              {poolInfo?.feeDisplay}
            </Text>
          </Block>
        </HStack>
      </VStack>
    </HStack>
  )
}

const TooltipInfo = ({ poolInfo }: { poolInfo: any }) => {
  const { getExplorerUrl } = useExplorer()
  return (
    <VStack align="flex-start">
      <HStack w="100%">
        <Image src={pool_img} w="20px" h="20px" />
        <Text fontSize="12px">Pool</Text>
        <AddressCopyLink
          address={poolInfo?.poolAddress}
          color="text_caption"
          onClickLink={() => {
            window.open(getExplorerUrl(poolInfo?.poolAddress, 'poolAddress'), '_blank')
          }}
        />
      </HStack>
      <Box h="1px" w="100%" bg="border" />
      <HStack w="100%">
        <SingleCoinImage
          imageUrl={poolInfo?.displayTokenA?.logo_url}
          w="20px"
          h="20px"
          showTag={!poolInfo?.displayTokenA?.is_trusted}
          showTagWidth="10px"
          showTagHeight="10px"
        />
        <Text fontSize="12px">{poolInfo?.displayTokenA.symbol}</Text>
        <AddressCopyLink
          address={poolInfo?.displayTokenA.address}
          color="text_caption"
          onClickLink={() => {
            window.open(getExplorerUrl(poolInfo?.displayTokenA.address, 'coin'), '_blank')
          }}
        />
      </HStack>
      <HStack w="100%">
        <SingleCoinImage
          imageUrl={poolInfo?.displayTokenB?.logo_url}
          w="20px"
          h="20px"
          showTag={!poolInfo?.displayTokenB?.is_trusted}
          showTagWidth="10px"
          showTagHeight="10px"
        />
        <Text fontSize="12px">{poolInfo?.displayTokenB.symbol}</Text>
        <AddressCopyLink
          address={poolInfo?.displayTokenB.address}
          color="text_caption"
          onClickLink={() => {
            window.open(getExplorerUrl(poolInfo?.displayTokenB.address, 'coin'), '_blank')
          }}
        />
      </HStack>
    </VStack>
  )
}
export default CoinPairInfo
